package zerovalue

// PROBLEM
//
// Counter only works if you remember to call NewCounter first. Declare one
// with var and use it, and the program crashes at run time with "assignment to
// entry in nil map". The compiler says nothing. The same trap appears every
// time a Counter is a field in another struct, or created by something that
// does not know about NewCounter.
//
// TRY IT
//
// Read TestBefore_ZeroValuePanics in zerovalue_test.go. It writes the two
// lines every caller would naturally write, and the second one panics.
//
// Do not edit this file. Your work goes in after.go.

// Counter counts how often each key was seen.
type Counter struct {
	counts map[string]int
}

// NewCounter returns a Counter that is ready to use.
func NewCounter() *Counter {
	return &Counter{counts: map[string]int{}}
}

// Inc adds one to the count for key.
func (c *Counter) Inc(key string) { c.counts[key]++ }

// Count returns how many times key was seen.
func (c *Counter) Count(key string) int { return c.counts[key] }
